import { parseDiffFromFile } from "@pierre/diffs";
import { parsePatchFiles } from "@pierre/diffs/utils/parsePatchFiles";
import { applyPatch, createTwoFilesPatch, parsePatch, reversePatch } from "diff";
import type { FileDiffMetadata } from "@pierre/diffs/types";

const DIFF_THEME_NAMES = {
  light: "pierre-light",
  dark: "pierre-dark",
} as const;

export type DiffThemeName = (typeof DIFF_THEME_NAMES)[keyof typeof DIFF_THEME_NAMES];

export function resolveDiffThemeName(theme: "light" | "dark"): DiffThemeName {
  return theme === "dark" ? DIFF_THEME_NAMES.dark : DIFF_THEME_NAMES.light;
}

const FNV_OFFSET_BASIS_32 = 0x811c9dc5;
const FNV_PRIME_32 = 0x01000193;
const SECONDARY_HASH_SEED = 0x9e3779b9;
const SECONDARY_HASH_MULTIPLIER = 0x85ebca6b;

export function fnv1a32(
  input: string,
  seed = FNV_OFFSET_BASIS_32,
  multiplier = FNV_PRIME_32,
): number {
  let hash = seed >>> 0;
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, multiplier) >>> 0;
  }
  return hash >>> 0;
}

export function buildPatchCacheKey(patch: string, scope = "diff-panel"): string {
  const normalizedPatch = patch.trim();
  const primary = fnv1a32(normalizedPatch, FNV_OFFSET_BASIS_32, FNV_PRIME_32).toString(36);
  const secondary = fnv1a32(
    normalizedPatch,
    SECONDARY_HASH_SEED,
    SECONDARY_HASH_MULTIPLIER,
  ).toString(36);
  return `${scope}:${normalizedPatch.length}:${primary}:${secondary}`;
}

export type RenderablePatch =
  | {
      kind: "files";
      files: FileDiffMetadata[];
      /** Binary file entries stripped from `files` — render as static rows, never as text diffs. */
      binaryFiles: FileDiffMetadata[];
      sourceFiles: FileDiffMetadata[];
    }
  | {
      kind: "raw";
      text: string;
      reason: string;
    };

export interface DiffLineStat {
  additions: number;
  deletions: number;
}

export function expandPartialPatchWithCurrentFile(
  patch: string,
  filePath: string,
  currentContents: string,
): string | null {
  const [parsedPatch, ...extraPatches] = parsePatch(patch);
  if (!parsedPatch || extraPatches.length > 0) return null;
  const oldContents = applyPatch(currentContents, reversePatch(parsedPatch));
  if (oldContents === false) return null;
  return createTwoFilesPatch(
    `a/${filePath}`,
    `b/${filePath}`,
    oldContents,
    currentContents,
    undefined,
    undefined,
    { context: Number.POSITIVE_INFINITY },
  );
}

export function getDiffLineStat(files: ReadonlyArray<FileDiffMetadata>): DiffLineStat {
  return files.reduce<DiffLineStat>(
    (total, file) => {
      for (const hunk of file.hunks) {
        total.additions += hunk.additionLines;
        total.deletions += hunk.deletionLines;
      }

      return total;
    },
    { additions: 0, deletions: 0 },
  );
}

interface RenderablePatchOptions {
  ignoreWhitespace?: boolean;
  /** Compact Pierre source offsets for partial-patch rows; retain collapsedBefore for separators. */
  compactPartialHunkOffsets?: boolean;
  /**
   * Pierre only allows expanding unmodified regions when a diff carries full
   * file contents (isPartial=false); patch-parsed diffs never do. When a
   * patch was generated with full context (git diff -U999999), its single
   * hunk holds the whole file, so rebuild the diff from those contents to
   * make unmodified regions expandable.
   */
  upgradeFullContextFiles?: boolean;
}

function upgradeFullContextFile(file: FileDiffMetadata): FileDiffMetadata {
  if (!file.isPartial || file.hunks.length !== 1) return file;
  const [hunk] = file.hunks;
  if (!hunk || hunk.deletionStart > 1 || hunk.additionStart > 1) return file;
  try {
    const oldName = file.prevName ?? file.name ?? "";
    const newName = file.name ?? oldName;
    if (!newName) return file;
    const upgraded = parseDiffFromFile(
      {
        // Parsed partial lines keep their trailing newlines, so plain concat
        // reconstructs the exact file contents.
        name: oldName || newName,
        contents: file.deletionLines.join(""),
        ...(file.cacheKey ? { cacheKey: `${file.cacheKey}:full-old` } : {}),
      },
      {
        name: newName,
        contents: file.additionLines.join(""),
        ...(file.cacheKey ? { cacheKey: `${file.cacheKey}:full-new` } : {}),
      },
    );
    return upgraded.hunks.length > 0 ? upgraded : file;
  } catch {
    return file;
  }
}

function hideWhitespaceChanges(file: FileDiffMetadata): FileDiffMetadata {
  let splitDelta = 0;
  let unifiedDelta = 0;
  const hunks = file.hunks.map((hunk) => {
    const oldContents = file.deletionLines
      .slice(hunk.deletionLineIndex, hunk.deletionLineIndex + hunk.deletionCount)
      .map((line) => `${line.replace(/\s/g, "")}\n`)
      .join("");
    const newContents = file.additionLines
      .slice(hunk.additionLineIndex, hunk.additionLineIndex + hunk.additionCount)
      .map((line) => `${line.replace(/\s/g, "")}\n`)
      .join("");
    const filtered = parseDiffFromFile(
      { name: file.name, contents: oldContents },
      { name: file.name, contents: newContents },
      { context: Infinity },
    ).hunks[0];
    const next = {
      ...hunk,
      additionLines: filtered?.additionLines ?? 0,
      deletionLines: filtered?.deletionLines ?? 0,
      hunkContent: filtered
        ? filtered.hunkContent.map((content) => ({
            ...content,
            additionLineIndex: content.additionLineIndex + hunk.additionLineIndex,
            deletionLineIndex: content.deletionLineIndex + hunk.deletionLineIndex,
          }))
        : [
            {
              type: "context" as const,
              lines: hunk.additionCount,
              additionLineIndex: hunk.additionLineIndex,
              deletionLineIndex: hunk.deletionLineIndex,
            },
          ],
      splitLineStart: hunk.splitLineStart + splitDelta,
      unifiedLineStart: hunk.unifiedLineStart + unifiedDelta,
      splitLineCount: filtered?.splitLineCount ?? hunk.additionCount,
      unifiedLineCount: filtered?.unifiedLineCount ?? hunk.additionCount,
    };
    splitDelta += next.splitLineCount - hunk.splitLineCount;
    unifiedDelta += next.unifiedLineCount - hunk.unifiedLineCount;
    return next;
  });
  return {
    ...file,
    hunks,
    splitLineCount: file.splitLineCount + splitDelta,
    unifiedLineCount: file.unifiedLineCount + unifiedDelta,
    ...(file.cacheKey ? { cacheKey: `${file.cacheKey}:ignore-whitespace` } : {}),
  };
}

function compactPartialHunkOffsets(file: FileDiffMetadata): FileDiffMetadata {
  if (!file.isPartial) return file;

  let splitLineStart = 0;
  let unifiedLineStart = 0;
  const hunks = file.hunks.map((hunk) => {
    const compactHunk = {
      ...hunk,
      splitLineStart,
      unifiedLineStart,
    };
    splitLineStart += hunk.splitLineCount;
    unifiedLineStart += hunk.unifiedLineCount;
    return compactHunk;
  });

  return {
    ...file,
    hunks,
    splitLineCount: splitLineStart,
    unifiedLineCount: unifiedLineStart,
    ...(file.cacheKey ? { cacheKey: `${file.cacheKey}:compact-partial` } : {}),
  };
}

/**
 * Collect the paths of files that git reported as binary in a unified patch
 * ("Binary files a/x and b/x differ" or a "GIT binary patch" section).
 *
 * @pierre/diffs' parser silently drops these markers, leaving a hunk-less
 * FileDiffMetadata whose virtualized rendering can crash the app. We detect
 * them from the raw patch text so they can be rendered as static rows instead.
 */
export function extractBinaryPatchPaths(patch: string): Set<string> {
  const binaryPaths = new Set<string>();
  const lines = patch.split("\n");
  let currentPaths: string[] = [];
  for (const rawLine of lines) {
    const line = rawLine.endsWith("\r") ? rawLine.slice(0, -1) : rawLine;
    if (line.startsWith("diff --git ")) {
      currentPaths = [];
      const match = /^diff --git (?:"?a\/(.+?)"?) (?:"?b\/(.+?)"?)$/.exec(line);
      if (match) {
        for (const path of [match[1], match[2]]) {
          if (path) currentPaths.push(path);
        }
      }
      continue;
    }
    if (line.startsWith("Binary files ") || line === "GIT binary patch") {
      if (line.startsWith("Binary files ")) {
        const match =
          /^Binary files (?:"?a\/(.+?)"?|\/dev\/null) and (?:"?b\/(.+?)"?|\/dev\/null) differ$/.exec(
            line,
          );
        if (match) {
          for (const path of [match[1], match[2]]) {
            if (path) binaryPaths.add(path);
          }
          continue;
        }
      }
      for (const path of currentPaths) {
        binaryPaths.add(path);
      }
    }
  }
  return binaryPaths;
}

function isBinaryFileDiff(file: FileDiffMetadata, binaryPaths: Set<string>): boolean {
  if (file.hunks.length !== 0) return false;
  const candidates = [file.name, file.prevName]
    .filter((name): name is string => typeof name === "string" && name.length > 0)
    .map((name) => (name.startsWith("a/") || name.startsWith("b/") ? name.slice(2) : name));
  return candidates.some((path) => binaryPaths.has(path));
}

export function getRenderablePatch(
  patch: string | undefined,
  cacheScope = "diff-panel",
  options: RenderablePatchOptions = {},
): RenderablePatch | null {
  if (!patch) return null;
  const normalizedPatch = patch.trim();
  if (normalizedPatch.length === 0) return null;

  try {
    // Parse the patch exactly as git wrote it. Trimming strips a hunk's trailing
    // blank context lines (a context line for an empty file line is just a
    // space), and the parser then reads that hunk shorter than its header claims.
    const parsedPatches = parsePatchFiles(patch, buildPatchCacheKey(patch, cacheScope));
    const sourceFiles = parsedPatches.flatMap((parsedPatch) => parsedPatch.files);
    const binaryPaths = extractBinaryPatchPaths(normalizedPatch);
    const files: FileDiffMetadata[] = [];
    const binaryFiles: FileDiffMetadata[] = [];
    for (const sourceFile of sourceFiles) {
      let file = sourceFile;
      if (options.upgradeFullContextFiles) {
        file = upgradeFullContextFile(file);
      }
      if (options.ignoreWhitespace) {
        file = hideWhitespaceChanges(file);
      }
      if (options.compactPartialHunkOffsets) {
        file = compactPartialHunkOffsets(file);
      }
      if (isBinaryFileDiff(file, binaryPaths)) {
        binaryFiles.push(file);
      } else {
        files.push(file);
      }
    }
    if (files.length > 0 || binaryFiles.length > 0) {
      return { kind: "files", files, binaryFiles, sourceFiles };
    }

    return {
      kind: "raw",
      text: normalizedPatch,
      reason: "Unsupported diff format. Showing raw patch.",
    };
  } catch {
    return {
      kind: "raw",
      text: normalizedPatch,
      reason: "Failed to parse patch. Showing raw patch.",
    };
  }
}

/**
 * Synthesize a renderable diff from before/after text (e.g. Claude Edit
 * old_string/new_string, which carry no provider patch). Line numbers are
 * relative to the snippet, not the source file.
 */
export function getRenderablePatchFromContents(
  oldContents: string,
  newContents: string,
  name: string,
  cacheScope = "inline-edit",
): RenderablePatch | null {
  if (oldContents === newContents) return null;
  try {
    const cacheKey = buildPatchCacheKey(
      `${name}\x00${oldContents}\x00\x00${newContents}`,
      cacheScope,
    );
    const fileDiff = parseDiffFromFile(
      { name, contents: oldContents, cacheKey: `${cacheKey}:old` },
      { name, contents: newContents, cacheKey: `${cacheKey}:new` },
    );
    if (fileDiff.hunks.length === 0) return null;
    return { kind: "files", files: [fileDiff], binaryFiles: [], sourceFiles: [fileDiff] };
  } catch {
    return null;
  }
}

/**
 * What the patch called the file, as the file's own name. Git writes a name holding a tab, a
 * newline, a quote or a backslash quoted and escaped, and the parser hands one of those back still
 * escaped. A viewed mark, a review comment and a file's contents are all asked for by this path,
 * and the host knows the file only under the name it really has.
 */
/** Uses the parser-decoded filename, including Git's quoted and escaped names. */

export function resolveFileDiffPath(fileDiff: FileDiffMetadata): string {
  return fileDiff.name ?? fileDiff.prevName ?? "";
}

export function resolveFileDiffPreviousPath(fileDiff: FileDiffMetadata): string {
  return fileDiff.prevName ?? fileDiff.name ?? "";
}

/** Includes change type to distinguish deletion/addition pairs for file-to-symlink changes. */
export function buildFileDiffIdentityKey(fileDiff: FileDiffMetadata): string {
  return `${resolveFileDiffPreviousPath(fileDiff)}\u0000${resolveFileDiffPath(fileDiff)}\u0000${fileDiff.type}`;
}

export function buildFileDiffRenderKey(fileDiff: FileDiffMetadata): string {
  const cacheKey = fileDiff.cacheKey;
  if (!cacheKey) return `${fileDiff.prevName ?? "none"}:${fileDiff.name}`;

  return cacheKey.endsWith(":hydrated") ? cacheKey.slice(0, -":hydrated".length) : cacheKey;
}

function hashFileDiffPart(hash: number, value: string | number | boolean | undefined): number {
  const serialized = value === undefined ? "undefined" : String(value);
  const withLength = fnv1a32(`${typeof value}:${serialized.length}:`, hash);
  return fnv1a32(serialized, withLength);
}

// Pierre's whole-patch cache key would repaint every file when one changes.
export function buildFileDiffContentVersion(fileDiff: FileDiffMetadata): number {
  let hash = FNV_OFFSET_BASIS_32;
  const append = (value: string | number | boolean | undefined) => {
    hash = hashFileDiffPart(hash, value);
  };

  append(fileDiff.name);
  append(fileDiff.prevName);
  append(fileDiff.lang);
  append(fileDiff.newObjectId);
  append(fileDiff.prevObjectId);
  append(fileDiff.mode);
  append(fileDiff.prevMode);
  append(fileDiff.type);
  append(fileDiff.isPartial);
  append(fileDiff.splitLineCount);
  append(fileDiff.unifiedLineCount);

  for (const line of fileDiff.additionLines) append(line);
  for (const line of fileDiff.deletionLines) append(line);
  for (const hunk of fileDiff.hunks) {
    append(hunk.collapsedBefore);
    append(hunk.additionStart);
    append(hunk.additionCount);
    append(hunk.additionLines);
    append(hunk.additionLineIndex);
    append(hunk.deletionStart);
    append(hunk.deletionCount);
    append(hunk.deletionLines);
    append(hunk.deletionLineIndex);
    append(hunk.hunkContext);
    append(hunk.hunkSpecs);
    append(hunk.splitLineStart);
    append(hunk.splitLineCount);
    append(hunk.unifiedLineStart);
    append(hunk.unifiedLineCount);
    append(hunk.noEOFCRAdditions);
    append(hunk.noEOFCRDeletions);
    for (const content of hunk.hunkContent) {
      append(content.type);
      append(content.additionLineIndex);
      append(content.deletionLineIndex);
      append(content.type === "change" ? content.additions : content.lines);
      append(content.type === "change" ? content.deletions : undefined);
    }
  }

  return hash;
}

export function getDiffCollapseIconClassName(fileDiff: FileDiffMetadata): string {
  switch (fileDiff.type) {
    case "new":
      return "text-[var(--diffs-addition-base)]";
    case "deleted":
      return "text-[var(--diffs-deletion-base)]";
    case "change":
    case "rename-pure":
    case "rename-changed":
      return "text-[var(--diffs-modified-base)]";
    default:
      return "text-muted-foreground/80";
  }
}

